n("בן", "בן הוא ילד ביחס להוריו, ומאותה מילה באים בעברית גם בנים ובנות. המילה משמשת גם בצירופים רבים, כמו בן בית, בן אדם ובן דוד. כשם פרטי בן הוא לרוב צורה קצרה של בנימין, וגם של שמות אחרים שנפתחים במילה בן.", ["בנימין"])
n("הילה", "הילה היא טבעת של אור שנראית לפעמים סביב השמש או הירח, כשהאור עובר דרך גבישי קרח דקים בעננים גבוהים. בהשאלה המילה מתארת גם את עיגול האור שמצויר סביב ראשן של דמויות בציורים עתיקים. בעברית של היום הילה היא גם רושם מיוחד שמשהו משאיר סביבו.")
n("נהוראי", "השם בנוי על המילה הארמית נהורא, שפירושה אור, עם הסיומת ־אי, שמוכרת משמות רבים מימי המשנה והתלמוד. מאותו שורש באה המילה העברית נהרה, אור ובהירות, שמופיעה כבר בעברית המקראית. בארמית אותה מילה משמשת גם בהשאלה, למי שמאיר ומבהיר.")
n("בר", "לבר יש כמה משמעויות. בארמית בר הוא בן, כמו בצירוף בר מצווה. בעברית בר הוא תבואה נקייה, וגם שדה פתוח שלא עובד, ומכאן חיות בר וצמחי בר. השם ניתן לבנים ולבנות, ומאותה מילה ארמית נבנה גם השם בראל.", ["בראל"])
n("ראם", "ראם הוא חיית בר חזקה שמוזכרת במקרא כמה פעמים, לרוב כתמונה של כוח. החוקרים אינם בטוחים איזו חיה היא, ויש שזיהו אותה עם שור הבר, שחי באזור בימי קדם. בתרגומים מאוחרים של המקרא תורגמה המילה לחד־קרן. כשם פרטי ראם נשמע גם כמו רם, גבוה.")
n("גיא", "גיא הוא עמק, שטח נמוך בין הרים או גבעות. המילה מופיעה במקרא פעמים רבות, ובספר ישעיהו היא חלק מתמונה של עמקים שמתרוממים והרים שמשתפלים, כדי לסלול דרך. בירושלים ובסביבתה יש מקומות שנקראים על שם גיא, כמו גיא בן הינום.")
n("דור", "דור הוא כל האנשים שחיים באותה תקופה, וגם הזמן שבין הורים לילדיהם. מכאן הצירוף מדור לדור, שמופיע בתהילים ובתפילה. בעברית המקראית דור הוא גם מקום מגורים, ודור היא גם עיר עתיקה על חוף הכרמל. מאותה מילה נבנו גם דורי ודוראל.", ["דורי", "דוראל"])
n("אלי", "אלי פירושו אלוהיי, והמילה מופיעה בשירת הים ובתהילים, בפנייה אישית אל האל. כשם פרטי אלי הוא לרוב צורה קצרה של שמות שנפתחים באלי, כמו אליהו ואלישע, ובמקרא אליהו נקרא גם אליה. באותה דרך נבנו בעברית שמות רבים שמחברים את אלי למילה נוספת.", ["אליהו", "אלישע", "אליה"])
n("מאור", "מאור הוא מקור של אור, כמו השמש והירח. בסיפור הבריאה המילה מתארת את המאור הגדול ואת המאור הקטן, שנתלו ברקיע. מאותו שורש, א־ו־ר, באים גם אור, מאיר ומאורי, ובעברית של היום המילה משמשת גם בהשאלה, כמו בצירוף מאור עיניים.", ["מאורי"])
n("זיו", "זיו הוא אור, זוהר ויופי, ובעברית של חז״ל המילה מתארת לרוב הדר של פנים. במקרא זיו הוא גם שמו הקדום של החודש השני בשנה, שנקרא היום אייר. בארמית המילה מופיעה באותו מובן של זוהר והדר. השם ניתן לבנים ולבנות.")
n("אריאה", "אריאה היא שיר לקול יחיד באופרה או ביצירה מוזיקלית גדולה אחרת. המילה הגיעה מהאיטלקית, שבה היא פירושה גם אוויר, וגם לחן ומנגינה. בעברית השם נשמע כמו אריה, ולכן אפשר לשמוע בו גם את החיה, אבל המילים באו משפות שונות.")
n("הדס", "הדס הוא שיח ירוק עד עם עלים ריחניים, שגדל בארץ ישראל ליד מים ובחורש. ענפי ההדס הם אחד מארבעת המינים בחג הסוכות. בספר ישעיהו ההדס מופיע בתמונה של צמחים טובים שעולים במקום קוצים. מאותה מילה נבנה גם השם הדסה, שמה העברי של אסתר.", ["הדסה"])
n("מלאק", "מלאק היא המילה הערבית למלאך, והיא באה מאותו שורש שמי של המילה העברית מלאך, שפירושה שליח. בעברית אותו שורש נמצא גם במילה מלאכה, עבודה שאדם נשלח לעשות. השם ניתן לבנים ולבנות.")
n("גבריאל", "השם מחבר את המילה גבר, במובן של כוח וגבורה, עם שם האל, ופירושו אלוהים הוא כוחי. בספר דניאל גבריאל הוא מלאך שבא להסביר לדניאל את החזונות שראה. השם מוכר גם במסורות אחרות ובשפות רבות, וגבריאלה היא הצורה שניתנת לבנות.", ["גבריאלה"])
n("כרמל", "כרמל בעברית המקראית הוא שדה פורה ומעובד, והמילה קרובה למילה כרם. הר הכרמל מתנשא מעל מפרץ חיפה, ובספר ישעיהו הדר הכרמל מוזכר לצד השרון. בתורה כרמל הוא גם שמם של גרגרים טריים של תבואה. השם ניתן לבנים ולבנות.")
n("מלאכי", "מלאכי פירושו השליח שלי, והשם בנוי על המילה מלאך, שבעברית המקראית היא קודם כל שליח. ספר מלאכי הוא האחרון בספרי תרי עשר, ויש חוקרים שחשבו שמלאכי הוא כינוי לנביא ולא שם פרטי. מאותו שורש באה גם המילה מלאכה.")
n("סנד", "סנד היא מילה ערבית שפירושה משען ותמיכה, מה שאפשר להישען עליו. מאותו שורש באה בערבית גם המילה אסנאד, שרשרת המוסרים של מסורת, שבה כל אחד נשען על מי שמסר לו. בערבית של היום המילה משמשת גם במובן של עזרה וגיבוי.")
n("אמילי", "אמילי היא הצורה האנגלית של אמיליה, שם שמקורו בשם המשפחה הרומי אמיליוס. מקור השם הרומי אינו ודאי, ויש שקשרו אותו למילה לטינית שפירושה מתחרה. מאותו שם רומי נבנו גם אמיליה ואמיל, הצורה שניתנת לבנים.", ["אמיליה", "אמיל"])
n("מסק", "מסק היא המילה הערבית למושק, חומר ריחני שהיה בושם יקר ונחשק בעולם העתיק. המילה עברה מהפרסית לערבית, ומשם לשפות רבות, ובעברית היא מוכרת בצורה מושק. בעברית מסק הוא גם קטיף הזיתים, אבל זו מילה אחרת.")
n("נור", "נור היא המילה הערבית לאור, וממנה באים בערבית שמות ומילים רבים. בארמית ובעברית של חז״ל נור הוא אש, ומאותו שורש באה בעברית המילה מנורה. השם ניתן לבנים ולבנות.")
n("אוריאל", "השם מחבר את המילה אורי, האור שלי, עם שם האל, ופירושו אלוהים הוא האור שלי. בדברי הימים אוריאל הוא ראש משפחה מבני קהת, מהלויים בימי דוד. במסורת היהודית אוריאל הוא גם שמו של אחד המלאכים. מאותה מילה נבנו גם אור, אורי, אוריה ואוראל.", ["אורי", "אור", "אוריה", "אוראל"])
n("נריה", "השם מחבר את המילה נר עם שם האל, ופירושו ה׳ הוא הנר שלי, כלומר האור שלי. בספר ירמיהו נריה הוא אביו של ברוך, הסופר שכתב את דברי ירמיהו. במקרא השם מופיע גם בצורה הארוכה נריהו, ומאותה מילה נבנה גם השם נרי.", ["נרי"])
n("תהל", "תהל בנוי על המילה תהילה, שבח, מהשורש ה־ל־ל, שממנו באים גם הלל והללויה. זה שם עברי קצר, ששומר על המילה תהילה בלי הסיומת שלה. הוא נשמע קרוב גם לשמות עבריים קצרים אחרים, כמו טל ותמר, אבל אין ביניהם קשר של מקור.", ["תהילה", "תהלה"])
n("אריה", "אריה הוא החיה הגדולה ממשפחת החתולים, שחיה בעבר גם בארץ ישראל. בברכת יעקב יהודה נקרא גור אריה, ומכאן האריה הוא סמל של שבט יהודה ושל ירושלים. ביידיש לייב הוא אריה, ומכאן השם הכפול אריה לייב. ארי היא מילה נוספת לאריה במקרא, וממנה נבנה גם אריאל.", ["ארי", "אריאל"])
n("ים", "ים הוא גוף מים גדול ומלוח, ובעברית המקראית המילה מתארת גם אגם גדול, כמו ים כנרת. בתהילים הים הגדול והרחב הוא חלק מתמונה של כל הבריאה. מפני שהים נמצא במערב הארץ, ים בעברית המקראית הוא גם צד מערב. השם ניתן לבנים ולבנות.")
n("שלום", "שלום בא מהשורש ש־ל־ם, שעניינו שלמות, ומכאן גם המובן של העדר מלחמה ושל רווחה. בעברית המילה משמשת גם כברכה בפגישה ובפרידה, ובשאלה מה שלומך. מאותו שורש נבנו גם השמות שלמה ושולמית. בתנ״ך שלום הוא גם שמו של אחד ממלכי ישראל.")
n("מאורי", "מאורי בנוי על המילה מאור, מקור של אור, עם סיומת של שייכות: המאור שלי. מאותו שורש, א־ו־ר, באים גם אור, אורי ומאיר. השם נבנה כמו שמות אחרים שמוסיפים יוד של שייכות למילה מוכרת, כמו שאורי נבנה מאור.", ["מאור"])
n("נחמה", "נחמה היא מה שמקל על הצער ומחזק אחרי אובדן, מהשורש נ־ח־ם. בתהילים המילה מתארת תקווה שמחזיקה בזמנים קשים. בשבת שאחרי תשעה באב, שבת נחמו, קוראים בבית הכנסת דברי נחמה מספר ישעיהו. מאותו שורש נבנו גם השמות נחום, נחמיה, מנחם ונחמן.")
n("עופרי", "עופרי בנוי על המילה עופר, צבי צעיר או בן איילה, עם סיומת של שייכות: העופר שלי. בשיר השירים הדוד משול לצבי או לעופר האיילים, כתמונה של קלות ותנועה. מאותה מילה בא גם השם עופר.", ["עופר"])
n("מחמוד", "מחמוד בא מהשורש הערבי ח־מ־ד, שעניינו שבח ותהילה, ופירושו מי שזוכה לשבח. מאותו שורש באים בערבית גם השמות מוחמד, אחמד וחמיד, והמילה חמד, שבח. בעברית אותו שורש מוכר במובן של חמדה ומשיכה, כמו בצירוף מחמד עיניים.")
n("שאם", "שאם היא השם הערבי של ארצות הלבנט, האזור שעל החוף המזרחי של הים התיכון, ובו סוריה, לבנון, ירדן וארץ ישראל. בערבית של היום המילה משמשת גם כשם של דמשק. יש שקשרו את המילה למילה הערבית שפירושה שמאל, כי האזור נמצא משמאל למי שפניו אל המזרח בחצי האי ערב.")
n("ברכה", "ברכה היא דברים טובים שאדם מאחל לאחר, וגם השפע עצמו. בתורה אברם מקבל הבטחה שיהיה ברכה, והמילה חוזרת בספר בראשית פעמים רבות. בתפילה היהודית ברכה היא נוסח קבוע שפותח במילה ברוך. מאותו שורש בא גם השם ברוך.")
n("אביטל", "השם מחבר את המילים אבי וטל, ופירושו אבי הוא טל. בתנ״ך אביטל היא אחת מנשות דוד ואמו של שפטיה, בנו החמישי. הטל, שיורד בלילות הקיץ ומרווה את הצמחים, הוא במקרא תמונה של ברכה ושל חיים.")
n("מילא", "מילא בא מהמילה הסלאבית מיל, שפירושה יקר ואהוב, ושנמצאת גם בשמות סלאביים כמו לודמילה ומילנה. בשפות סלאביות רבות המילה הזאת היא חלק משמות של בנים ושל בנות. מילה הוא כתיב אחר של אותו שם.", ["מילה"])
n("מריה", "מריה היא הצורה היוונית והלטינית של מרים, השם העברי העתיק. דרך היוונית והלטינית עבר השם לשפות רבות באירופה ובעולם, ובכל אחת קיבל צורה משלו. מקור השם מרים אינו ודאי, ויש שקשרו אותו למילה מר או למילה מצרית שפירושה אהובה.", ["מרים"])
n("זיין", "זיין היא מילה ערבית שפירושה יופי וחן, ובערבית היא משמשת גם כתואר למשהו נאה וטוב. מאותו שורש באה בערבית המילה זינה, קישוט, וממנה גם השם זינה, שנכתב בעברית גם זיינה. כך נבנו מאותה מילה שם לבנים ושם לבנות.", ["זינה", "זיינה"])
n("יהושע", "השם מחבר את שם האל עם הפועל הושיע, ופירושו ה׳ מושיע. בתורה הושע בן נון הוא משרתו של משה, ומשה הוסיף לשמו את היוד וקרא לו יהושע. אחרי מות משה הוביל יהושע את בני ישראל בכניסה לארץ, ועל שמו נקרא ספר יהושע.")
n("ידידיה", "השם מחבר את המילה ידיד, אהוב, עם שם האל, ופירושו אהובו של ה׳. בתנ״ך זה השם שנתן נתן הנביא לשלמה, בנם של דוד ובת שבע. מאותה מילה באים גם ידיד וידידות, ובעברית של היום ידיד הוא חבר קרוב.", ["ידיד"])
n("אלחנן", "השם מחבר את שם האל עם הפועל חנן, ופירושו אלוהים חנן, כלומר נתן במתנה ובחסד. בתנ״ך אלחנן בן דודו מבית לחם הוא אחד מגיבורי דוד. מאותו פועל נבנו שמות עבריים רבים, כמו חנן, יוחנן וחנה.")
n("סמא", "סמא היא מילה ערבית שפירושה השמיים, וגם גובה ורוממות, מהשורש ס־מ־ו. המילה קרובה למילה העברית שמיים, ושתי המילים באות ממקור שמי משותף. בערבית המילה מופיעה גם בשירה, כתמונה של מרחב ושל גובה.")
n("צפורה", "ציפורה בנויה על המילה ציפור, ושמות רבים מתקופת המקרא נקראו על שם בעלי חיים, כמו דבורה, רחל ויעל. בתורה ציפורה היא בתו של יתרו, כוהן מדיין, ומשה נשא אותה לאישה אחרי שברח ממצרים. בתורה השם נכתב בכתיב חסר, צפורה.")
n("רועי", "רועי בנוי על המילה רועה, מי ששומר על הצאן ומוביל אותו למרעה, עם סיומת של שייכות: הרועה שלי. בתהילים המילה פותחת מזמור מוכר שבו ה׳ מתואר כרועה ששומר ומשגיח. מאותו שורש, ר־ע־ה, באה גם המילה מרעה.")
n("יגל", "יגל הוא פועל בצורת עתיד מהשורש ג־י־ל, ופירושו ישמח ויגיל. בתהילים המילה מופיעה בתמונה של לב ששמח בישועה. מאותו שורש באות המילים גיל וגילה, שתיהן במובן של שמחה.")
n("נחמן", "נחמן בנוי על השורש נ־ח־ם, כמו נחמה ומנחם, ופירושו מי שמנחם. השם מוכר מספרות חז״ל, ובתלמוד יש כמה חכמים בשם רב נחמן. מאותו שורש נבנו גם השמות נחום ונחמיה.")
n("תום", "תום הוא יושר, שלמות ותמימות, מהשורש ת־מ־ם, ובעברית המקראית המילה מתארת מי שהולך בדרך ישרה. מכאן גם הצירוף תום לב, כוונה טובה ופשוטה. באנגלית תום הוא צורה קצרה של תומאס, שם שמקורו בארמית ופירושו תאום. מאותה מילה עברית בא גם השם תם.", ["תם"])
n("אופיר", "אופיר היא ארץ שמוזכרת במקרא כמקור של זהב, ולשם שלחו שלמה וחירם מלך צור אוניות. החוקרים לא יודעים בדיוק איפה הייתה אופיר, והציעו מקומות בערב, באפריקה ובהודו. בעברית זהב אופיר הוא זהב טהור ומשובח. השם ניתן לבנים ולבנות.")
n("אן", "אן היא הצורה הצרפתית והאנגלית של חנה, שהגיעה לאירופה דרך היוונית והלטינית, בצורה אנה. חנה בנויה על השורש ח־נ־ן, שעניינו חן וחסד. בעברית השם קצר מאוד, ונשמע כמו המילה אן, כלומר לאן.", ["אנה", "חנה"])
n("ניל", "ניל הוא שם בכמה שפות. באירלנד ניל הוא שם גאלי עתיק, ויש שפירשו אותו כאלוף או כענן, אבל המקור אינו ודאי. בערבית ניל הוא שמו של נהר הנילוס, וגם השגה של מטרה. השם קצר ונכתב בעברית בשלוש אותיות.")
n("דן", "דן בא מהשורש ד־י־ן, ופירושו שפט וקבע משפט. בתורה דן הוא בנו של יעקב ובלהה, שפחת רחל, ורחל קראה לו כך כי אמרה שאלוהים דן אותה. ממנו יצא שבט דן, ועל שם השבט נקראה העיר דן בצפון, ליד מקורות הירדן. מאותו שורש נבנה גם השם דניאל.", ["דניאל"])
n("רון", "רון הוא שיר ושמחה, מהשורש ר־נ־ן, ובעברית המקראית המילה מופיעה בתמונה של כוכבי בוקר ששרים יחד. מאותו שורש באות המילים רינה ורננה, ומאותה מילה נבנו גם רן, רוני, רני, רונה ורינה.", ["רוני", "רני", "רן", "רינה", "רונה"])
n("ח'אלד", "השם בא מהשורש הערבי ח־ל־ד, שעניינו נצח והמשכיות, ופירושו מי שחי לעד ונשאר לתמיד. בערבית אותו שורש משמש במילים רבות שקשורות לזיכרון ולהנצחה. בעברית השורש מוכר מהמילה חלד, שבעברית המקראית פירושה עולם וימי החיים.")
n("יסכה", "יסכה מוזכרת בתורה פעם אחת, כבתו של הרן ואחותה של מלכה, ובכך היא אחייניתו של אברהם. בתורה לא מסופר עליה דבר מעבר לשמה. בפרשנות מקובל לקשר את השם לפועל סכה, להביט ולראות, ויש פרשנים שזיהו אותה עם שרה.")
n("עומרי", "עומרי בנוי על המילה עומר, אלומה של שיבולים שנקצרו, עם סיומת של שייכות. בתנ״ך עמרי הוא מלך ישראל שקנה את הר שומרון ובנה עליו את העיר שומרון, שהייתה לבירת הממלכה. מאותה מילה בא גם השם עומר.", ["עומר"])
n("יהב", "יהב בארמית פירושו נתן, ומכאן המילה מתארת נתינה ומתנה. בעברית המקראית המילה מופיעה בתהילים, בתמונה של אדם שמשליך את יהבו על ה׳, כלומר מפקיד בידיו את מה שמטריד אותו. בעברית של היום יהב הוא גם משא ואחריות.")
n("שוהם", "שוהם הוא אבן יקרה, אחת האבנים בחושן של הכהן הגדול, ושתי אבני שוהם נקבעו על כתפי האפוד ועליהן נחקקו שמות השבטים. זיהוי האבן אינו ודאי, ויש שזיהו אותה עם אבן האוניקס. שוהם הוא גם שמו של יישוב במרכז הארץ. השם ניתן לבנים ולבנות.")
n("אביה", "השם מחבר את המילה אבי עם שם האל, ופירושו ה׳ הוא אבי. בתנ״ך השם ניתן לגברים ולנשים: אביה הוא מלך יהודה, בנו של רחבעם, ואביה בת זכריהו היא אמו של חזקיהו המלך. בדברי הימים המלך נקרא גם אביהו, בצורה הארוכה של השם.", ["אביהו"])
n("יאר", "יאר הוא פועל בצורת עתיד מלשון האיר, ובברכת כוהנים ה׳ מתבקש להאיר את פניו אל העם. זה כתיב קצר של השם יאיר, ולשניהם אותה משמעות. מאותו שורש באים גם אור, מאיר ומאורי.", ["יאיר"])
n("ריאן", "ריאן הוא שם ערבי מהשורש ר־ו־י, שעניינו השקיה ורוויה, ופירושו מי שרווה ושופע. בעברית אותו שורש מוכר מהמילים רוויה ורווה. השם ניתן לבנים ולבנות, ונכתב בעברית גם רייאן.", ["רייאן"])
n("שמס", "שמס היא המילה הערבית לשמש, ומאותו מקור שמי באות גם המילה העברית שמש והמילה הארמית שמשא. בערבית המילה מופיעה גם בצירופים ובכינויים רבים, ובשירה היא תמונה של אור ושל חום. השם קצר ונשמע קרוב מאוד למילה העברית.")
n("ירדן", "הירדן הוא הנהר שזורם מצפון הארץ אל ים כנרת, ומשם דרומה אל ים המלח. במקרא חציית הירדן היא רגע הכניסה לארץ, ולוט ראה את כל ככר הירדן כשבחר לו מקום. את שם הנהר נוהגים לקשר לפועל ירד, כי הוא יורד מצפון לדרום, אבל המקור אינו ודאי. השם ניתן לבנים ולבנות.")
n("לוי", "בתורה לוי הוא בנו השלישי של יעקב ולאה, ולאה קראה לו כך בתקווה שאישה ילווה אליה. ממנו יצא שבט לוי, שבניו שירתו במשכן ובמקדש, ומהם גם הכוהנים. השם קשור למילים ליווי וחיבור, מהשורש ל־ו־ה.")
n("ליאו", "ליאו פירושו אריה בלטינית, והשם עבר משם לשפות רבות באירופה. בשפות שונות הוא גם צורה קצרה של שמות כמו ליאון וליאונרדו, שבנויים על אותה מילה. ליאון הוא הצורה היוונית, ומשמעה זהה.", ["ליאון"])
n("עברי", "עברי הוא בן לעם העברי, ובתורה אברם הוא הראשון שנקרא העברי. מקור הכינוי אינו ודאי, ויש שקשרו אותו לעבר, אחד מאבותיו של אברהם, ויש שפירשו אותו כמי שבא מעבר הנהר. מאותה מילה נקראת גם השפה העברית.")
n("אביתר", "השם מחבר את המילה אבי עם יתר, מלשון שפע ועודף, ופירושו אבי הוא שפע. בתנ״ך אביתר הוא כהן, בנו של אחימלך, שנמלט כשנהרגו כוהני נוב והצטרף אל דוד. מאז היה אביתר מהכוהנים שליוו את דוד בימי מלכותו.")
n("זוהר", "זוהר הוא אור חזק ובוהק, ובספר דניאל המילה מתארת את זוהר הרקיע. בעברית של היום המילה משמשת גם בהשאלה, למשל בצירוף ימי הזוהר. ספר הזוהר, החיבור המרכזי של הקבלה, נקרא על שם המילה הזאת. השם ניתן לבנים ולבנות.")

